// Focused review refinements; account/company subscription content remains unchanged.
state.organizationConsent='이벤트 참여 및 경품 지급을 위해 이름과 휴대전화 번호를 수집·이용합니다.\n수집 주체: [입력]\n보유 기간: [입력]';
function consentContent(){return state.settings.consentText||state.organizationConsent}
function logoSymbol(){return `<svg class="kit-logo" viewBox="0 0 40 40" aria-hidden="true"><rect x="1" y="1" width="38" height="38" rx="12" fill="#222"/><path d="M12 12h9a9 9 0 0 1 0 18h-9z" fill="none" stroke="#fff" stroke-width="3.5" stroke-linejoin="round"/><path d="m18 18 7 3-7 3z" fill="#f6cbae"/></svg>`}
index=function(){return ''};
const polishShell=shell;shell=function(body){let h=polishShell(body).replace('<b class="logo-mark">d.</b>',logoSymbol()).replace(/<span class="demo-badge">DEMO<\/span>/,'');if(eventRoutes.includes(route())&&!state.gameDraftMode)h=h.replace(/<div class="breadcrumbs">[\s\S]*?<\/div>/,`<div class="breadcrumbs"><a href="#workspace">워크스페이스</a><span>/</span><a href="#workspace-detail" data-return-brand>${esc(currentBrand().name)}</a><span>/</span><strong>${esc(state.eventName||'새 행사')}</strong></div>`);return h};
const polishHome=home;home=function(){if(state.filter==='종료')state.filter='전체';return polishHome().replace(/<button class="btn" data-action="new">[\s\S]*?<\/button>/,'').replace(/<button class="chip [^"]*" data-filter="종료">종료<\/button>/,'')};
const runningTable=eventTable;eventTable=function(){let h=runningTable();if(route()==='home')h=h.replace(/<tr[^>]*data-event-status="종료"[^>]*>[\s\S]*?<\/tr>/g,'');return h};
const workspaceName=workspace;workspace=function(){return workspaceName().replace('＋ 브랜드 추가','워크스페이스 추가').replaceAll('브랜드 추가','워크스페이스 추가')};
const modalNew=action;action=function(a,n){modalNew(a,n);if(a==='brand-new'){const modal=app.querySelector('.modal');if(modal)modal.innerHTML=modal.innerHTML.replaceAll('브랜드 추가','워크스페이스 추가').replace('브랜드 이름','워크스페이스 이름');bind()}};
const reviewStateOpen=openWorkspaceEvent;openWorkspaceEvent=function(n){const key=n.dataset.eventBrand+'|'+n.dataset.openEvent,saved=state.eventMemory[key];reviewStateOpen(n);if(!saved&&['검토 중','시작 예정','진행 중','종료'].includes(n.dataset.eventStatus)){state.consent=true;if(state.approved)state.settings.reviewApproval={signature:approvalSignature(),status:'확정',time:'저장된 확정 시안'};retainEvent();render()}};
const defaultForm=editorForm;editorForm=function(){return defaultForm().replace('제작 담당자: ','').replace(/(<textarea id="consent-text">)[\s\S]*?(<\/textarea>)/,`$1${esc(consentContent())}$2`)};
const consentPreview=settingPreview;settingPreview=function(kind){let h=consentPreview(kind);if(kind==='수집·동의')h=h.replace(/<div class="preview-consent">[\s\S]*?<\/div>/,`<div class="preview-consent">${esc(consentContent())}</div>`);return h};
const consentSignature=approvalSignature;approvalSignature=function(){return JSON.stringify({config:consentSignature(),effectiveConsent:consentContent()})};
const defaultBranding=whitelabel;whitelabel=function(){return defaultBranding().replace('<details class="mt">',`<div class="field"><label for="default-consent">기본 동의 문구</label><textarea id="default-consent">${esc(state.organizationConsent)}</textarea><p class="mini-label">행사에 별도 문구가 없으면 사용합니다.</p></div><details class="mt">`)};
const saveDefaultBranding=action;action=function(a,n){if(a==='brand-save'){const input=document.getElementById('default-consent');if(input)state.organizationConsent=input.value.trim()||state.organizationConsent}saveDefaultBranding(a,n)};
const consentReviewPage=review;review=function(){return consentReviewPage().replace('기본 동의 문구',esc(consentContent())).replace('시안·경품 검토','브랜드 게임 검토')};
const consentCustomerPage=brandReview;brandReview=function(){return consentCustomerPage().replaceAll('시안·참여정보·경품 확정','게임 확정').replaceAll('시안·경품 확정','게임 확정').replace('기본 동의 문구',esc(consentContent()))};
const reviewButtons=publish;publish=function(){return reviewButtons().replace('시안 확정','게임 확정')};
function rankedTemplateChoices(){const spec=state.gameDraft||{kind:currentTemplate().kind,season:/가을/.test(state.eventName)?'가을':'',useCase:/박람회/.test(state.eventName)?'박람회':/팝업/.test(state.eventName)?'팝업스토어':''};const ranking=new Map(recommendGameBases(spec).map(r=>[r.id,r]));return gameTemplates.map(t=>({t,rank:ranking.get(t.id)})).sort((a,b)=>(b.rank?.score||0)-(a.rank?.score||0))}
function openTemplatePicker(){app.insertAdjacentHTML('beforeend',`<div class="modal-overlay"><section class="modal template-picker" role="dialog" aria-modal="true" aria-label="템플릿 변경"><div class="panel-head"><h2>템플릿 변경</h2><button data-create="close" aria-label="닫기">${uiIcon('close')}</button></div><div class="template-gallery">${rankedTemplateChoices().map(({t,rank})=>`<article class="template-card">${templateStage(t,false)}<div class="template-info"><h3>${t.title}</h3><p class="template-desc">${t.desc}</p>${rank?`<p class="mini-label">${rank.reasons.join(' · ')}</p>`:''}<button class="btn secondary wide" data-replace-template="${t.id}">${t.id===state.selectedTemplate?'선택됨':'선택'}</button></div></article>`).join('')}</div></section></div>`);bind()}
function replaceGameTemplate(id){if(id===state.selectedTemplate){document.querySelector('.modal-overlay')?.remove();return}const settings=state.settings,eventName=state.eventName,basic=state.basic,mode=state.gameDraftMode,brand=state.brandId,oldDraft=state.gameDraft;state.selectedTemplate=id;resetLayers();state.settings=settings;state.eventName=eventName;state.basic=basic;state.brandId=brand;state.gameDraftMode=mode;state.gameDraft=oldDraft?{...oldDraft,kind:currentTemplate().kind,baseId:id,title:currentTemplate().title+' 초안'}:null;invalidateApproval();state.editorTab='디자인';render();toast('템플릿을 변경했습니다. 경품과 행사 정보는 유지됩니다.')}
const summaryModal=draftSummary;draftSummary=function(){return summaryModal().replace(/<details>[\s\S]*?<\/details>/,'<button class="text-link" data-pick-template>템플릿 변경</button>')};
function dataSummary(){return `<section class="panel data-summary"><div class="panel-head"><h2>데이터 요약</h2><span class="mini-label">${state.ended?'최종 집계':'현재 집계'}</span></div><div class="grid cols-4">${[['참여 수','3,412'],['순참여자','2,980'],['당첨 수','860'],['발송 성공률',state.retried?'100%':'99.4%']].map(([label,value])=>`<div><span class="mini-label">${label}</span><strong>${value}</strong></div>`).join('')}</div></section>`}
state.includeAISummary=true;
const dataReport=report;report=function(){let h=dataReport().replace(steps('report'),steps('report')+dataSummary());h=h.replace('<h3>공개 지표</h3>','<h3>리포트 구성</h3>');h=h.replace('<div class="ai-panel mt">',`<label class="checkbox ai-include"><input type="checkbox" id="include-ai-summary" ${state.includeAISummary?'checked':''}>AI 결과 요약 포함</label><div class="ai-panel mt">`);if(!state.includeAISummary){h=h.replace(/<div class="ai-panel mt">[\s\S]*?<div class="field"><label>공개 시점<\/label>/,'<div class="field"><label>공개 시점</label>');h=h.replace('확정된 보고문이 여기에 표시됩니다.','').replace(esc(state.reportText),'')}h=h.replace('✓ 담당자 확정','확정 완료');return h};
const includedBrandReport=brandReport;brandReport=function(){let h=includedBrandReport();if(!state.includeAISummary)h=h.replace(/<section class="panel"><div class="eyebrow">EVENT HIGHLIGHTS<\/div>[\s\S]*?<\/section>/,'');return h};
const reportIncludeAction=action;action=function(a,n){if(a==='share-report'&&!state.includeAISummary){const ai=state.aiReport;state.aiReport=false;reportIncludeAction(a,n);state.aiReport=ai;return}reportIncludeAction(a,n)};
const polishBind=bind;bind=function(){polishBind();app.querySelectorAll('.studio-bottom a[href="#templates"]').forEach(n=>{if(['editor','prizes','game-draft'].includes(route()))n.onclick=e=>{e.preventDefault();openTemplatePicker()}});app.querySelectorAll('[data-pick-template]').forEach(n=>n.onclick=openTemplatePicker);app.querySelectorAll('[data-replace-template]').forEach(n=>n.onclick=()=>replaceGameTemplate(n.dataset.replaceTemplate));const include=document.getElementById('include-ai-summary');if(include)include.onchange=()=>{state.includeAISummary=include.checked;render()};};
screens.find(s=>s[0]==='brand-review')[2]='게임 확정';render();
const saveAIOptionBind=bind;bind=function(){saveAIOptionBind();const include=document.getElementById('include-ai-summary');if(include)include.onchange=()=>{state.includeAISummary=include.checked;state.settings.includeAISummary=include.checked;render()}};
const savedAIReport=report;report=function(){state.includeAISummary=state.settings.includeAISummary!==false;return savedAIReport()};
const savedAISummary=brandReport;brandReport=function(){state.includeAISummary=state.settings.includeAISummary!==false;let h=savedAISummary();if(!state.includeAISummary)h=h.replace('grid-template-columns:1.4fr 1fr','grid-template-columns:1fr');return h};
render();
